arguments.command:
python3 -c "
import json
with open('/app/resources/treasury_bulletin_1953_01.json') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in list(d.items())[:5]:
            print(' ' * indent + str(k))
            if isinstance(v, dict):
                print_structure(v, indent+2)
            elif isinstance(v, list):
                print(' ' * (indent+2) + f'[{len(v)} items]')
    elif isinstance(d, list):
        print(' ' * indent + f'[{len(d)} items]')

print_structure(data)
"
